  "findings": [
    {
      "ref": "[D524]",
      "area": "age_gating",
      "claim": "The FTC will not bring enforcement actions under COPPA against general audience sites that collect personal information of children solely for age verification via age-verification technologies, even without first obtaining verifiable parental consent.",
      "stance": "neutral",
      "quote": "The Federal Trade Commission (“FTC”) issued a policy statement announcing that it will not bring enforcement actions under the Children’s Online Privacy Protection Rule (“COPPA Rule”) against operators of general audience and mixed-audience websites or online services that collect, use, or disclose personal information of children for the sole purpose of determining a user’s age via age-verification technologies, even without first obtaining verifiable parental consent."
    }
  ]
